import sys, os
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'app', 'js')
def patch(fn, pairs):
    p = os.path.join(root, fn); s = open(p, encoding='utf8').read()
    for old, new in pairs:
        if old not in s: print('NAO ACHEI em', fn, ':', old[:90]); sys.exit(1)
        s = s.replace(old, new, 1)
    open(p, 'w', encoding='utf8').write(s)

# ---------- levels.js: geometria dos novos tipos + um objeto diferente por pergunta ----------
patch('levels.js', [
 ("mimic: (p) => ({ x: p * TS + 6, y: g * TS - 20, w: 20, h: 20 }) }[type];",
  "mimic: (p) => ({ x: p * TS + 6, y: g * TS - 20, w: 20, h: 20 }), barrel: (p) => ({ x: p * TS + 4, y: g * TS - 24, w: 24, h: 24 }), balloon: (p) => ({ x: p * TS + 6, y: g * TS - 78, w: 20, h: 26 }) }[type];"),
 ("    const STY = ['ped', 'bump', 'mimic', 'door'];\n    for (let s = 0; s < nStations; s++) { section(secs[s] || 4); station(s, false, STY[(d * 3 + s) % 4]); }",
  "    // um objeto DIFERENTE por pergunta (em cada fase os 3 são distintos; nas 3 fases aparecem os 6 tipos)\n    const STY = { 1: ['barrel', 'door', 'bump'], 2: ['balloon', 'mimic', 'ped'], 3: ['bump', 'barrel', 'balloon'] }[d];\n    for (let s = 0; s < nStations; s++) { section(secs[s] || 4); station(s, false, STY[s % 3]); }"),
])

